import{AudioParamRadius,InputPortRadius,LeftSideTopPadding,TotalInputPortHeight,TotalOutputPortHeight,TotalParamPortHeight}from"./GraphStyle.js";export const calculateInputPortXY=t=>({x:0,y:InputPortRadius+LeftSideTopPadding+t*TotalInputPortHeight});export const calculateOutputPortXY=(t,o,a)=>{const{width:r,height:u}=o;return{x:r,y:u/2+(2*t-a+1)*TotalOutputPortHeight/2}};export const calculateParamPortXY=(t,o)=>({x:0,y:o+TotalParamPortHeight*(t+1)-AudioParamRadius});